mapper.select:
select  from basket_event_player
where division_id = #{divisionId}
  and source_player_id = #{sourcePlayerId}
  and is_delete = 0
  and roster_version_id is null
  and roster_version_id = #{rosterVersionId}
limit 1

mapper.insert:
insert into basket_event_player (
    season_id, division_id, roster_version_id, event_team_id, source_player_id, member_id, platform_identity_id, platform_code, game_id_snapshot, player_name_snapshot, avatar_file_id, position, jersey_no, is_captain, is_starter, event_player_status, create_time, update_time, is_delete
) values (
    #{seasonId}, #{divisionId}, #{rosterVersionId}, #{eventTeamId}, #{sourcePlayerId}, #{memberId}, #{platformIdentityId}, #{platformCode}, #{gameIdSnapshot}, #{playerNameSnapshot}, #{avatarFileId}, #{position}, #{jerseyNo}, #{isCaptain}, #{isStarter}, #{eventPlayerStatus}, #{createTime}, #{updateTime}, #{isDelete}
)
